//! The map view's parts that do not need the app (DESIGN.md §10 "Map view"): Web Mercator
//! projection ([`proj`]), the camera ([`Camera`]), hierarchical grid clustering of photo
//! positions per zoom level ([`Clusters`]), the offline base map ([`World`], Natural Earth land,
//! lakes and borders, generated by `gen/world.py` into `data/world.bin`) and its GPU renderer
//! ([`MapRenderer`]).
//!
//! [`ogc`] reads what online map services (WMS, WMTS, WFS, OGC API, STAC) offer and builds
//! the addresses to ask them for.
//!
//! Nothing here talks to a network. Raster tiles have a seam ([`TileSource`]) and no
//! implementation; see its docs.

pub mod basemap;
pub mod camera;
pub mod cluster;
pub mod ogc;
pub mod proj;
pub mod render;
pub mod tiles;
pub mod world;

pub use camera::Camera;
pub use cluster::{Cluster, Clusters, declutter};
pub use proj::{project, unproject};
pub use render::{MapRenderer, Style};
pub use tiles::{TileSource, TileState};
pub use world::World;

/// Logical pixels per world unit at zoom 0 (the usual web map tile).
pub const TILE: f64 = 256.0;

/// The deepest zoom the camera goes to (about street level; the base map is long out of
/// detail by then, pins still separate).
pub const MAX_ZOOM: f64 = 19.0;
